KEYS='id zh en palette history form material layout font ui use avoid combine title motifs source'.split()
STYLES=[dict(zip(KEYS,x)) for x in DATA]
def dump(p,obj):
    p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(obj,ensure_ascii=False,indent=2),encoding='utf8')
def write(p,s):
    p=Path(p);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(s,encoding='utf8')
for i,s in enumerate(STYLES):
    s['no']=i+1;s['group']=['建筑与平面艺术','自然与人文艺术','未来科技与数字艺术'][0 if i<6 else 1 if i<12 else 2]
    s['palette']=['#'+v for v in s['palette'].split()]
